--
-- Table structure for table `tickets`
--

DROP TABLE IF EXISTS `tickets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tickets` (
  `tick_id` varchar(36) NOT NULL DEFAULT (uuid()),
  `subject` varchar(255) NOT NULL,
  `priority` enum('LOW','MEDIUM','HIGH','URGENT') DEFAULT 'MEDIUM',
  `acc_id` varchar(36) NOT NULL,
  `sender_email` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `status` enum('OPEN','IN_PROGRESS','PENDING_CUSTOMER','RESOLVED','CLOSED') DEFAULT 'OPEN',
  `sentiment_score` float DEFAULT NULL,
  `category` varchar(100) DEFAULT NULL,
  `ai_accuracy` float DEFAULT NULL,
  `analyzed_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`tick_id`),
  KEY `acc_id` (`acc_id`),
  CONSTRAINT `tickets_ibfk_1` FOREIGN KEY (`acc_id`) REFERENCES `accounts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

